import {COMMERCIAL_SECTORS as SECTORS,COMMERCIAL_INTERESTS as INTERESTS,OFFER_FIELDS as FIELDS,OFFER_STATES as STATES} from './commercial-schema.js';
export function createCommercialUI({api,esc,getState,getBoot,openDialog,closeDialog,toast}){
  let active=false,admin=false,data=null,org='',sequence=0,pending=false,filter='all';
  const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);
  const date=n=>new Date(n).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});
  const url=()=>admin?'/api/portal/commercial-admin':'/api/portal/commercial-proposals';
  const button=(label,action,id='',primary=false)=>`<button type="button" class="p-button ${primary?'primary':'secondary'}" data-commercial="${action}" data-id="${esc(id)}">${esc(label)}</button>`;
  const input=(key,label,value='',type='text',required=true,more='')=>`<label class="p-field"><span>${esc(label)}</span><input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${more}></label>`;
  const area=(key,label,value='',required=true,max=5000)=>`<label class="p-field"><span>${esc(label)}</span><textarea name="${key}" rows="3" maxlength="${max}" ${required?'required':''}>${esc(value)}</textarea></label>`;
  const check=(key,label)=>`<label class="assisted-check"><input name="${key}" type="checkbox" required><span>${esc(label)}</span></label>`;
  const form=(kind,action,r,body,submit='Confirmar')=>`<form data-commercial-form="${action}" data-kind="${kind}" data-id="${esc(r?.id||'')}" data-version="${r?.version||0}" data-key="${crypto.randomUUID()}">${body}<p class="form-error" role="alert" hidden></p><button class="p-button primary">${esc(submit)}</button></form>`;
  const link=(href,label)=>`<a class="p-button secondary" href="${esc(href)}" target="_blank" rel="noopener">${esc(label)}</a>`;
  function offerSummary(r){const p=r.versions.at(-1);return `<p class="overline">${esc(r.company)} · ${esc(STATES[r.state])}</p><h3>${esc(p.title)}</h3><p><strong>${money(p.priceCents)}</strong> · versão ${p.number}</p><p>Válida até ${esc(p.validUntil.split('-').reverse().join('/'))}, às 23h59 (Brasília).</p>${FIELDS.map(([k,label])=>`<h4>${label}</h4><p class="commercial-text">${esc(p[k])}</p>`).join('')}<p class="micro-copy">O aceite registra o acordo desta versão. Nenhuma cobrança, renovação ou liberação automática de serviço é executada nesta tela.</p>`;}
  function paint(){const root=document.querySelector('#commercial-workspace');if(!active||!root)return;if(!data){root.innerHTML='<p>Carregando…</p>';return;}
    const offers=data.offers||[];
    const offerCards=`<section><h2>${admin?'Propostas privadas':'Suas propostas'}</h2><div class="commercial-grid">${offers.map(r=>`<article class="panel commercial-card"><p class="overline">${esc(r.company)} · ${esc(STATES[r.state])}</p><h3>${esc(r.versions.at(-1).title)}</h3><p>${money(r.versions.at(-1).priceCents)} · versão ${r.versions.length}</p>${admin?`<p>Destinatário: ${esc(r.recipientEmail)}</p>`:''}${button('Abrir proposta','offer-detail',r.id)}</article>`).join('')||'<p>Nenhuma proposta recebida nesta conta.</p>'}</div></section>`;
    if(!admin){root.innerHTML=`<p>Propostas dirigidas à sua conta. Confira empresa, entregas e condições antes de aceitar. As propostas de consultoria ficam em <a href="#/consultations">Consultorias</a>.</p>${button('Atualizar propostas','refresh')}${offerCards}`;return;}
    const leads=data.leads.filter(r=>filter==='all'||r.state===filter),names={new:'Novo interesse',contacted:'Contato realizado',proposal:'Em proposta',closed:'Encerrado',do_not_contact:'Não contatar'};
    root.innerHTML=`<aside class="commercial-notice">${data.leads.filter(x=>x.state==='new').length} novo(s) interesse(s). Os contatos chegam aqui; esta área não dispara mensagens.</aside><div class="assisted-toolbar">${button('Criar apresentação','new','',true)}${button('Atualizar comercial','refresh')}</div><section><h2>Apresentações</h2><div class="commercial-grid">${data.pages.map(r=>`<article class="panel commercial-card"><p class="overline">${esc(SECTORS[r.draft.sector].name)} · ${r.published?'Link público ativo':'Somente rascunho'}</p><h3>${esc(r.draft.company||r.draft.headline)}</h3><p>${r.published?'Edição pública '+r.published.number+'. Salvar alterações não troca a versão pública.':'Revise a apresentação antes de liberar o link.'}</p><div class="assisted-actions">${button('Editar','edit',r.id)}${button('Reutilizar base','duplicate',r.id)}${link('/apresentacao.html?preview='+encodeURIComponent(r.id),'Prévia restrita ↗')}${button(r.published?'Atualizar link público':'Liberar link público','publish',r.id)}${r.published?link('/apresentacao.html?id='+r.slug,'Abrir apresentação ↗')+button('Copiar link','copy',r.id)+button('Desativar link','unpublish',r.id):''}</div></article>`).join('')||'<p>Crie uma base por setor e personalize apenas o necessário para cada conversa.</p>'}</div></section><section><h2>Interesses recebidos</h2><label class="p-field"><span>Etapa do contato</span><select id="commercial-filter"><option value="all">Todas</option>${Object.entries(names).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="commercial-grid">${leads.map(r=>`<article class="panel commercial-card"><p class="overline">${esc(names[r.state])} · ${esc(date(r.createdAt))}</p><h3>${esc(r.company)}</h3><p>${esc(r.name)} · ${esc(r.email)}</p><p>Retorno autorizado por ${r.channel==='email'?'e-mail':'WhatsApp: '+esc(r.phone)}.</p><p>${r.interests.map(k=>esc(INTERESTS[k])).join(' · ')}</p>${r.note?`<p class="commercial-text">${esc(r.note)}</p>`:''}${r.operatorNote?`<p>Equipe: ${esc(r.operatorNote)}</p>`:''}<div class="assisted-actions">${button('Registrar andamento','lead',r.id)}${r.state!=='do_not_contact'?button('Preparar proposta privada','new-offer',r.id):''}</div><p class="micro-copy">Autorização limitada ao retorno desta solicitação. Não autoriza campanhas em massa.</p></article>`).join('')||'<p>Nenhum interesse nesta etapa.</p>'}</div></section>${offerCards}`;
  }
  async function load(){const seq=++sequence,mode=admin,company=org;try{const next=await api(url());if(active&&seq===sequence&&admin===mode&&company===org){data=next;paint();}}catch(e){if(active&&seq===sequence)document.querySelector('#commercial-workspace').innerHTML=`<p role="alert">${esc(e.message)}</p>${button('Tentar novamente','refresh')}`;}}
  function pageForm(r,duplicate=false){const d=r?.draft||{sector:'general',...SECTORS.general},assets=(duplicate?getState().assets:[...new Map([...(r&&r.orgId!==org?[]:getState().assets||[]),...(d.media||[])].map(a=>[a.id,a])).values()]).filter(a=>['image/png','image/jpeg','image/webp','video/mp4'].includes(a.mime));
    openDialog(duplicate?'Reutilizar apresentação':r?'Editar apresentação':'Criar apresentação',form('page','save',duplicate?null:r,`<p>A página será pública quando liberada. Use somente contexto conferido e materiais autorizados. Não inclua preço negociado, contato pessoal ou relatório privado.</p><label class="p-field"><span>Setor</span><select name="sector">${Object.entries(SECTORS).map(([k,v])=>`<option value="${k}" ${d.sector===k?'selected':''}>${v.name}</option>`).join('')}</select></label>${button('Usar texto deste setor','sector-copy')}${input('company','Empresa apresentada (opcional)',duplicate?'':d.company||'','text',false,'maxlength="120"')}${input('headline','Mensagem principal',d.headline,'text',true,'maxlength="180"')}${area('problem','Problema reconhecível',d.problem,true,1500)}${area('application','Aplicações para o setor',d.application,true,1500)}<details><summary>Contexto público conferido (opcional)</summary>${area('context','Observação sobre a empresa',duplicate?'':d.context||'',false,1500)}${input('source','Fonte pública HTTPS',duplicate?'':d.source||'','url',false,'maxlength="1000"')}${input('checkedAt','Data da conferência',duplicate?'':d.checkedAt||'','date',false)}</details><fieldset class="commercial-examples"><legend>Exemplos · até seis arquivos de 3 MB</legend><p>Adicione arquivos pela Biblioteca da sua empresa de origem antes de montar a apresentação. Nomeie cada exemplo e identifique se é ilustrativo ou real.</p>${assets.map(a=>{const selected=!duplicate&&d.media?.find(x=>x.id===a.id);return `<div class="commercial-example" data-example="${esc(a.id)}"><label class="assisted-check"><input type="checkbox" name="mediaIds" value="${esc(a.id)}" ${selected?'checked':''}><span>${esc(a.name)}</span></label><label class="p-field"><span>Legenda do exemplo</span><input data-caption value="${esc(selected?.caption||'')}" maxlength="300"></label><label class="p-field"><span>Identificação</span><select data-mode><option value="demonstration">Demonstração ilustrativa</option><option value="real" ${selected?.mode==='real'?'selected':''}>Material real autorizado</option></select></label></div>`;}).join('')||'<p>Nenhum arquivo disponível. É possível salvar sem exemplos; a apresentação não alegará possuir demonstrações que não foram anexadas.</p>'}</fieldset>`,'Salvar rascunho'),true);
  }
  function pageConfirm(r,action){openDialog(action==='publish'?'Liberar apresentação pública':'Desativar apresentação',form('page',action,r,action==='publish'?`<p>Esta ação torna a versão atual do rascunho acessível a qualquer pessoa com o link. A prévia restrita deve ser conferida antes de liberar.</p>${link('/apresentacao.html?preview='+encodeURIComponent(r.id),'Abrir prévia restrita ↗')}${check('publicConsent','Conferi a página e autorizo o conteúdo público, incluindo nome e contexto da empresa. Não há informações privadas.')}${check('materialConsent','Tenho autorização para exibir os materiais e identifiquei corretamente exemplos ilustrativos e materiais reais. Não há resultados comerciais inventados.')}`:'<p>O link público e os exemplos deixam de ser servidos. Pessoas que já visualizaram podem ter guardado cópias. Contatos e propostas permanecem privados no portal.</p>'),true);}
  function pricingPicker(){return '<fieldset><legend>Base de uma oferta revisada (opcional)</legend><p>Preenche entregas, condições e preço normal. Confira o acordo antes de disponibilizar; descontos de lançamento não são aplicados automaticamente.</p><label class="p-field"><span>Ficha revisada</span><select name="pricingSource"><option value="">Preencher manualmente</option>'+((data?.pricingSources||[]).map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · revisão '+p.revision+'</option>').join(''))+'</select></label>'+button('Preencher com esta ficha','pricing-copy')+'<input type="hidden" name="pricingPlanId"><input type="hidden" name="pricingVersion"><p data-pricing-origin class="micro-copy"></p></fieldset>';}
  function offerForm(lead,r){const p=r?.versions.at(-1)||{};openDialog('Preparar proposta privada',form('offer','send',r,`<p>Empresa: <strong>${esc(r?.company||lead.company)}</strong>. O destinatário precisa ter conta na Helpu. Nenhum e-mail ou WhatsApp será enviado por este botão.</p>${r?`<p>Destinatário fixo: ${esc(r.recipientEmail)}</p>`:input('recipientEmail','E-mail de login do destinatário',lead.email,'email',true,'maxlength="254"')+`<input type="hidden" name="leadId" value="${esc(lead.id)}">`}${pricingPicker()}${input('title','Título da proposta',p.title||'','text',true,'maxlength="150"')}${input('price','Valor total (R$)',p.priceCents?p.priceCents/100:'','number',true,'min="0.01" step="0.01"')}${input('validUntil','Validade da proposta',p.validUntil||'','date')}${FIELDS.map(([k,label])=>area(k,label,p[k]||'')).join('')}<p class="micro-copy">Para assinatura, informe explicitamente periodicidade, preço de renovação e cancelamento. Preencher esta proposta não ativa uma assinatura ou plano.</p>`,'Disponibilizar no portal'),true);}
  function offerDetail(r){let actions='';if(admin&&r.state!=='accepted'){actions+=button('Preparar nova versão','revise-offer',r.id)+button('Retirar proposta','withdraw',r.id);}if(!admin&&r.state==='sent'){actions+=button('Aceitar esta proposta','accept',r.id,true)+button('Pedir ajuste','changes',r.id);}openDialog('Proposta privada',`<div class="commercial-detail">${offerSummary(r)}${r.customerNote?`<aside class="commercial-notice">Pedido de ajuste: ${esc(r.customerNote)}</aside>`:''}${r.withdrawalNote?`<p>Motivo da retirada: ${esc(r.withdrawalNote)}</p>`:''}${r.acceptance?`<p>Aceite registrado para a versão ${r.acceptance.number}, em ${esc(date(r.acceptance.at))}.</p>`:''}<div class="assisted-actions">${actions}</div><details><summary>Histórico e versões anteriores</summary>${r.versions.slice(0,-1).map(v=>`<details><summary>Versão ${v.number} · ${money(v.priceCents)}</summary><h4>${esc(v.title)}</h4>${FIELDS.map(([k,label])=>`<p><strong>${label}</strong></p><p class="commercial-text">${esc(v[k])}</p>`).join('')}</details>`).join('')}${r.history.map(e=>`<p>${esc(date(e.at))} · ${esc({send:'Proposta disponibilizada',accept:'Aceite registrado',changes:'Ajuste solicitado',withdraw:'Proposta retirada'}[e.action]||e.action)}</p>`).join('')}</details></div>`,true);}
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-commercial]');if(!active||!b||pending)return;const a=b.dataset.commercial,id=b.dataset.id,r=data?.pages?.find(x=>x.id===id),offer=data?.offers?.find(x=>x.id===id),lead=data?.leads?.find(x=>x.id===id);
    if(a==='pricing-copy'){const f=b.closest('form'),source=data?.pricingSources?.find(x=>x.id===f.elements.pricingSource.value);if(!source){f.elements.pricingPlanId.value='';f.elements.pricingVersion.value='';f.querySelector('[data-pricing-origin]').textContent='Sem vínculo com ficha. Confira os campos preenchidos.';return;}for(const k of ['title',...FIELDS.map(([k])=>k)])f.elements[k].value=source.proposal[k];f.elements.price.value=source.proposal.priceCents/100;f.elements.pricingPlanId.value=source.id;f.elements.pricingVersion.value=source.version;f.querySelector('[data-pricing-origin]').textContent='Base: '+source.name+' · revisão '+source.revision+'. Preço normal; revise eventuais condições especiais.';return;}
    if(a==='refresh'){load();return;}if(a==='new'){pageForm();return;}if(a==='sector-copy'){const f=b.closest('form'),s=SECTORS[f.elements.sector.value];for(const k of ['headline','problem','application'])f.elements[k].value=s[k];return;}if(a==='edit'&&r){pageForm(r);return;}if(a==='duplicate'&&r){pageForm(r,true);return;}if(['publish','unpublish'].includes(a)&&r){pageConfirm(r,a);return;}if(a==='copy'&&r){const value=location.origin+'/apresentacao.html?id='+r.slug;try{await navigator.clipboard.writeText(value);toast('Link copiado.');}catch{openDialog('Link público',`<p>Copie o endereço abaixo:</p><p class="commercial-text">${esc(value)}</p>`);}return;}
    if(a==='lead'&&lead){openDialog('Registrar andamento do contato',form('interest','status',lead,`<label class="p-field"><span>Etapa</span><select name="state">${Object.entries({new:'Novo interesse',contacted:'Contato realizado',proposal:'Em proposta',closed:'Encerrado',do_not_contact:'Não contatar'}).map(([k,v])=>`<option value="${k}" ${lead.state===k?'selected':''}>${v}</option>`).join('')}</select></label>${area('note','Observação da equipe',lead.operatorNote||'',false,1500)}<p>Marcar Não contatar bloqueia novas propostas por esta solicitação. O botão não envia mensagens.</p>`));return;}
    if(a==='new-offer'&&lead){offerForm(lead);return;}if(a==='offer-detail'&&offer){offerDetail(offer);return;}if(a==='revise-offer'&&offer){offerForm(null,offer);return;}if(offer&&['accept','changes','withdraw'].includes(a)){openDialog(a==='accept'?'Aceitar proposta':'Registrar ajuste',form('offer',a,offer,a==='accept'?offerSummary(offer)+check('consent','Li e aceito esta versão do valor, escopo, entregas, prazos, pagamento e demais condições.'):area('note',a==='withdraw'?'Motivo da retirada':'O que precisa mudar?','',true,a==='withdraw'?1500:2000)),true);}
  });
  document.addEventListener('change',e=>{if(active&&e.target.id==='commercial-filter'){filter=e.target.value;paint();}});
  document.addEventListener('submit',async e=>{const f=e.target.closest('[data-commercial-form]');if(!active||!f)return;e.preventDefault();if(pending)return;const fd=new FormData(f),input={...Object.fromEntries(fd),action:f.dataset.commercialForm,kind:f.dataset.kind,id:f.dataset.id||undefined,version:Number(f.dataset.version),orgId:org,requestKey:f.dataset.key,publicConsent:fd.get('publicConsent')==='on',materialConsent:fd.get('materialConsent')==='on',consent:fd.get('consent')==='on'};if(input.kind==='page'&&input.action==='save')input.media=[...f.querySelectorAll('[data-example]')].filter(el=>el.querySelector('input[type=checkbox]').checked).map(el=>({id:el.dataset.example,caption:el.querySelector('[data-caption]').value,mode:el.querySelector('[data-mode]').value}));if(input.kind==='offer'&&input.action==='send'){input.priceCents=Math.round(Number(input.price)*100);if(input.pricingPlanId)input.pricingVersion=Number(input.pricingVersion);}pending=true;const button=f.querySelector('button:not([type])'),mode=admin,company=org;button.disabled=true;try{await api(url(),'POST',input);if(active&&mode===admin&&company===org){closeDialog();await load();toast('Alteração registrada.');}}catch(error){const el=f.querySelector('[role=alert]');el.textContent=error.message;el.hidden=false;}finally{pending=false;button.disabled=false;}});
  return {page(mode=false){return `<section class="page-heading"><div><p class="overline">${mode?'OPERAÇÃO HELPU':'PROPOSTAS'}</p><h1>${mode?'Apresentações e conversas.':'O próximo passo, com clareza.'}</h1><p>${mode?'Personalize a apresentação pública e acompanhe os pedidos de contato.':'Revise as condições preparadas para sua empresa.'}</p></div></section><div id="commercial-workspace"></div>`;},mount(view){const next=['commercial','proposals'].includes(view);if(!next){active=false;++sequence;return;}active=true;admin=view==='commercial';org=getState()?.company.id||'';data=null;if(admin&&!getBoot()?.operator){document.querySelector('#commercial-workspace').innerHTML='<p>Acesso restrito à equipe autorizada.</p>';return;}paint();load();}};
}
